package main

import (
	"embed"

	"github.com/nsgo-dev/game/packages/game/project"
)

// gameYAML is Lantern 3D's project file, holding its window size, appearance and export presets.
//
//go:embed game.yaml
var gameYAML []byte

// gameProject is the parsed game.yaml.
var gameProject = project.MustParse(gameYAML)

// levelScenePath is the scene file the 3D level is built from, by its path from the project root.
const levelScenePath = "assets/shrine.scene.yaml"

// projectFiles holds the level's scene file and the binary glTF 2.0 diorama it names, generated by tools/genassets/main.go (CC0-1.0, see CREDITS.md), at their paths from the project root, as scenemodel.Assets reads them.
//
//go:embed assets/shrine.scene.yaml assets/lantern_shrine.glb
var projectFiles embed.FS
